// AI Usage Note: generated by Claude; every case checked against ConcertUaEventProvider by running the tests.
import assert from 'node:assert/strict';
import { describe, test } from 'node:test';
import { ConcertUaEventProvider } from '../../dist/infra/providers/concert-ua-event-provider.js';
import { concertUaSampleFeed } from '../../dist/infra/providers/concert-ua-sample-feed.js';

const aRecord = (overrides: Record<string, unknown> = {}) => ({
  id: 'cu-1',
  title: 'Jazz evening',
  description: 'Live quartet.',
  genre: 'Concert',
  venue: { name: 'Caribbean Club', address: 'Kyiv', lat: 50.46, lng: 30.52 },
  startsAt: '2026-10-22T19:00:00+03:00',
  endsAt: '2026-10-22T22:00:00+03:00',
  ...overrides,
});

describe('ConcertUaEventProvider.normalize', () => {
  const provider = new ConcertUaEventProvider(() => Promise.resolve([]));

  test('converts a record to our event model with UTC times', () => {
    assert.deepEqual(provider.normalize(aRecord()), {
      event: {
        externalId: 'cu-1',
        title: 'Jazz evening',
        description: 'Live quartet.',
        categoryName: 'Concerts',
        venue: { name: 'Caribbean Club', address: 'Kyiv', location: { lat: 50.46, lng: 30.52 } },
        startsAt: '2026-10-22T16:00:00.000Z',
        endsAt: '2026-10-22T19:00:00.000Z',
      },
    });
  });

  test('turns a numeric id into a string', () => {
    const result = provider.normalize(aRecord({ id: 1002 }));

    assert.equal('event' in result && result.event.externalId, '1002');
  });

  test('ends an event without an end time at the end of its day in Kyiv', () => {
    const { endsAt: _endsAt, ...withoutEnd } = aRecord();

    const result = provider.normalize(withoutEnd);

    // Starts 19:00 on 22 October in Kyiv (UTC+3), so it ends at 23:59:59.999 that day.
    assert.equal('event' in result && result.event.endsAt, '2026-10-22T20:59:59.999Z');
  });

  const genres = [
    { genre: 'Concert', category: 'Concerts' },
    { genre: 'FESTIVAL', category: 'Concerts' },
    { genre: 'exhibition', category: 'Exhibitions' },
  ];
  for (const { genre, category } of genres) {
    test(`maps the genre "${genre}" to ${category}`, () => {
      const result = provider.normalize(aRecord({ genre }));

      assert.equal('event' in result && result.event.categoryName, category);
    });
  }

  test('skips a genre with no category and names the genre', () => {
    assert.deepEqual(provider.normalize(aRecord({ genre: 'Comedy' })), {
      skip: { externalId: 'cu-1', reason: 'Genre "Comedy" has no category' },
    });
  });

  test('cuts a title longer than the API allows to 120 characters', () => {
    const result = provider.normalize(aRecord({ title: 'x'.repeat(130) }));

    assert.equal('event' in result && result.event.title.length, 120);
    assert.equal('event' in result && result.event.title.endsWith('…'), true);
  });

  const invalid = [
    { title: 'a missing title', record: { title: undefined }, field: 'title' },
    { title: 'an empty title', record: { title: '   ' }, field: 'title' },
    { title: 'a date that is not a date', record: { startsAt: 'next friday' }, field: 'startsAt' },
    { title: 'a date without an offset', record: { startsAt: '2026-10-22T19:00:00' }, field: 'startsAt' },
    {
      title: 'a venue without an address',
      record: { venue: { name: 'Club', lat: 50, lng: 30 } },
      field: 'venue.address',
    },
    {
      title: 'a latitude out of range',
      record: { venue: { name: 'C', address: 'A', lat: 91, lng: 30 } },
      field: 'venue.lat',
    },
  ];
  for (const { title, record, field } of invalid) {
    test(`skips a record with ${title}`, () => {
      assert.deepEqual(provider.normalize(aRecord(record)), {
        skip: { externalId: 'cu-1', reason: `Invalid record: ${field}` },
      });
    });
  }

  const notRecords = [null, undefined, 42, 'text', []];
  for (const raw of notRecords) {
    test(`skips ${JSON.stringify(raw) ?? 'undefined'} without throwing`, () => {
      assert.deepEqual(provider.normalize(raw), { skip: { externalId: null, reason: 'Invalid record: record' } });
    });
  }
});

describe('ConcertUaEventProvider.fetch', () => {
  test('returns what the feed loader gives', async () => {
    const feed = [aRecord()];

    assert.deepEqual(await new ConcertUaEventProvider(() => Promise.resolve(feed)).fetch(), feed);
  });

  test('reads the sample feed by default, with one usable event per kind and three unusable records', async () => {
    const provider = new ConcertUaEventProvider();

    const results = (await provider.fetch()).map((raw) => provider.normalize(raw));

    assert.equal(results.filter((result) => 'event' in result).length, 3);
    assert.equal(results.filter((result) => 'skip' in result).length, 3);
  });
});

describe('concertUaSampleFeed', () => {
  test('counts its dates from the given day', () => {
    const feed = concertUaSampleFeed(new Date('2026-10-15T09:00:00Z')) as { startsAt: string }[];

    assert.equal(feed[0]?.startsAt, '2026-10-20T16:00:00.000Z');
  });
});
